// StudentBean getters and setters
public class Q01 {public static class StudentBean {private int id;private String name;private double grade;public StudentBean(){}public int getId(){return id;}public void setId(int id){this.id=id;}public String getName(){return name;}public void setName(String name){this.name=name;}public double getGrade(){return grade;}public void setGrade(double grade){this.grade=grade;}}public static void main(String[] args){StudentBean s=new StudentBean();s.setId(101);s.setName("Asha");s.setGrade(86.5);System.out.println(s.getId()+" "+s.getName()+" "+s.getGrade());}}
